# ======================================================
# CypraTeam AGENT INSTALLER - PORTABLE
# Generates all Modfiles and registers every agent on the
# CypraTeam portable Ollama endpoint (127.0.0.1:11435),
# using the host's ollama.exe but a project-local model
# store. Nothing is written to the host's normal Ollama
# service or its default model store.
# ======================================================

[CmdletBinding()]
param(
    [string]$TargetModel = "huihui_ai/gemma-4-abliterated:e4b",
    [string]$ProjectRoot = $PSScriptRoot,
    [string]$LocalHost = "127.0.0.1:11435",
    # Leave blank/omit to install ALL agents. Pass a single agent name
    # (e.g. -AgentName "cypra") to generate + register just that one.
    [string]$AgentName = "",
    [ValidateSet('','Status','PullBase','RegisterCore','RegisterAll','Rebuild')]
    [string]$Job = ""
)

$ErrorActionPreference = "Stop"

# Resolve the project root. Deliberately NOT taken from a quoted batch argument:
# %~dp0 always ends in a trailing backslash, and "%VAR%" with a trailing backslash
# right before the closing quote is misparsed by Windows' argv parser (the backslash
# escapes the quote instead of closing it), which then swallows any arguments that
# follow. Self-locating via $PSScriptRoot avoids that class of bug entirely.
if ([string]::IsNullOrWhiteSpace($ProjectRoot)) { $ProjectRoot = $PSScriptRoot }
if ([string]::IsNullOrWhiteSpace($ProjectRoot)) { $ProjectRoot = Split-Path -Parent $MyInvocation.MyCommand.Path }
$ProjectRoot = $ProjectRoot.Trim().Trim('"').TrimEnd('\','/')
if (-not (Test-Path -LiteralPath $ProjectRoot -PathType Container)) {
    throw "Project root does not exist: $ProjectRoot"
}
$ProjectRoot = (Resolve-Path -LiteralPath $ProjectRoot).Path
$ModfileDir = Join-Path $ProjectRoot "Modfiles"
$ModelStore = Join-Path $ProjectRoot "OllamaModels"
New-Item -ItemType Directory -Force -Path $ModfileDir | Out-Null
New-Item -ItemType Directory -Force -Path $ModelStore | Out-Null

if (-not (Get-Command ollama -ErrorAction SilentlyContinue)) {
    throw "ollama.exe was not found in PATH. Install Ollama on this PC first (the engine is shared; only the model store and port are portable)."
}

function Test-OllamaReady {
    param([string]$OllamaHost)
    try {
        $r = Invoke-RestMethod -Uri ("http://{0}/api/tags" -f $OllamaHost) -Method Get -TimeoutSec 4 -ErrorAction Stop
        return $true
    } catch { return $false }
}

function Start-OllamaEndpoint {
    param([string]$OllamaHost, [Parameter(Mandatory)][string]$ModelStore)
    if (Test-OllamaReady $OllamaHost) { return }
    $parts = $OllamaHost -split ':',2
    $listen = if ($parts.Count -eq 2) { "http://$($parts[0]):$($parts[1])" } else { "http://$OllamaHost" }
    # Explicitly set OLLAMA_MODELS in the spawned process so the portable endpoint
    # never falls back to the host's default model store.
    $cmd = "`$env:OLLAMA_HOST='$listen'; `$env:OLLAMA_MODELS='$ModelStore'; & ollama serve"
    Start-Process -FilePath "powershell.exe" -WindowStyle Hidden -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-Command',$cmd) | Out-Null
    for ($i=0; $i -lt 30; $i++) {
        Start-Sleep -Milliseconds 500
        if (Test-OllamaReady $OllamaHost) { return }
    }
    throw "Ollama endpoint $OllamaHost did not become ready."
}

function Invoke-Ollama {
    param(
        [Parameter(Mandatory)][string]$OllamaHost,
        [Parameter(Mandatory)][string[]]$Arguments,
        [Parameter(Mandatory)][string]$ModelStore
    )
    $oldHost = $env:OLLAMA_HOST
    $oldStore = $env:OLLAMA_MODELS
    try {
        $env:OLLAMA_HOST = $OllamaHost
        $env:OLLAMA_MODELS = $ModelStore
        & ollama @Arguments
        $rc = $LASTEXITCODE
        if ($rc -ne 0) { throw "ollama $($Arguments -join ' ') failed on $OllamaHost with exit code $rc." }
    } finally {
        if ($null -eq $oldHost) { Remove-Item Env:OLLAMA_HOST -ErrorAction SilentlyContinue } else { $env:OLLAMA_HOST = $oldHost }
        if ($null -eq $oldStore) { Remove-Item Env:OLLAMA_MODELS -ErrorAction SilentlyContinue } else { $env:OLLAMA_MODELS = $oldStore }
    }
}

Write-Host "[PORTABLE] Ollama endpoint: $LocalHost" -ForegroundColor Cyan
Write-Host "[PORTABLE] Model store:     $ModelStore" -ForegroundColor Cyan
Write-Host "[*] Base model: $TargetModel" -ForegroundColor Yellow
Write-Host "[*] Registration scope: CypraTeam portable Ollama only (127.0.0.1:11435)." -ForegroundColor Green
Write-Host "[*] The host's normal Ollama service and default model store are never touched." -ForegroundColor Green
Write-Host "[*] Modfiles will be written to: $ModfileDir" -ForegroundColor Cyan

Start-OllamaEndpoint -OllamaHost $LocalHost -ModelStore $ModelStore

function Get-PortableModelNames {
    $oldHost = $env:OLLAMA_HOST
    $oldStore = $env:OLLAMA_MODELS
    try {
        $env:OLLAMA_HOST = $LocalHost
        $env:OLLAMA_MODELS = $ModelStore
        $rows = @(& ollama list 2>$null)
    } finally {
        if ($null -eq $oldHost) { Remove-Item Env:OLLAMA_HOST -ErrorAction SilentlyContinue } else { $env:OLLAMA_HOST = $oldHost }
        if ($null -eq $oldStore) { Remove-Item Env:OLLAMA_MODELS -ErrorAction SilentlyContinue } else { $env:OLLAMA_MODELS = $oldStore }
    }
    $names = @()
    foreach ($row in $rows) {
        $line = ([string]$row).Trim()
        if ([string]::IsNullOrWhiteSpace($line) -or $line -match '^NAME\s') { continue }
        $parts = $line -split '\s+'
        if ($parts.Count -ge 1) { $names += $parts[0] }
    }
    return $names
}

function Register-ExistingModelfiles {
    param([string[]]$OnlyNames)
    $files = @(Get-ChildItem -LiteralPath $ModfileDir -Filter 'Modelfile_*' -File -ErrorAction SilentlyContinue)
    if ($OnlyNames -and $OnlyNames.Count -gt 0) {
        $want = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
        foreach ($n in $OnlyNames) { [void]$want.Add($n) }
        $files = @($files | Where-Object { $want.Contains(($_.Name -replace '^Modelfile_','')) })
    }
    $ok = 0
    $fail = 0
    $i = 0
    foreach ($f in $files) {
        $i++
        $agent = $f.Name -replace '^Modelfile_',''
        Write-Host "[$i/$($files.Count)] Registering $agent from existing Modelfile..." -ForegroundColor DarkYellow
        try {
            Invoke-Ollama -OllamaHost $LocalHost -ModelStore $ModelStore -Arguments @('create',$agent,'-f',$f.FullName)
            $ok++
        } catch {
            Write-Host "[!] $agent : $($_.Exception.Message)" -ForegroundColor Red
            $fail++
        }
    }
    Write-Host ""
    Write-Host "[+] Registered $ok   failed $fail   from existing Modelfiles (SYSTEM text not rewritten)." -ForegroundColor Green
}

if ($Job -eq 'Status') {
    $mfs = @(Get-ChildItem -LiteralPath $ModfileDir -Filter 'Modelfile_*' -File -ErrorAction SilentlyContinue)
    $reg = @(Get-PortableModelNames)
    Write-Host ""
    Write-Host "STATUS" -ForegroundColor Cyan
    Write-Host "  Modelfiles on disk : $($mfs.Count)"
    Write-Host "  Registered models  : $($reg.Count)"
    Write-Host "  Base (config/default): $TargetModel"
    $hasBase = $false
    foreach ($n in $reg) { if ($n -eq $TargetModel -or $n -like "$TargetModel*") { $hasBase = $true } }
    if ($hasBase) { Write-Host "  Base present       : yes" -ForegroundColor Green } else { Write-Host "  Base present       : no (use job 2 / PullBase)" -ForegroundColor Yellow }
    Write-Host ""
    Write-Host "  Single agents: pick an ID in the Matrix. You do not need a full install."
    exit 0
}

if ($TargetModel -match '^(?i)(q|quit|exit)$') {
    Write-Host "Cancelled." -ForegroundColor Yellow
    exit 0
}

if ($Job -eq 'PullBase') {
    Write-Host "[*] Pulling base into portable store: $TargetModel" -ForegroundColor Yellow
    try { Invoke-Ollama -OllamaHost $LocalHost -ModelStore $ModelStore -Arguments @('show',$TargetModel) } catch {
        Invoke-Ollama -OllamaHost $LocalHost -ModelStore $ModelStore -Arguments @('pull',$TargetModel)
    }
    Write-Host "[+] Base ready. Open the Matrix and pick an agent ID to register it." -ForegroundColor Green
    exit 0
}

if ($Job -eq 'RegisterCore') {
    Register-ExistingModelfiles -OnlyNames @('cypra','anomaly','quantum','nexus-prime')
    exit 0
}

if ($Job -eq 'RegisterAll') {
    Register-ExistingModelfiles
    exit 0
}

# Job Rebuild (or legacy no -Job): generate Modelfiles then register.

Write-Host "[*] Verifying base model on the portable store..." -ForegroundColor Cyan
try { Invoke-Ollama -OllamaHost $LocalHost -ModelStore $ModelStore -Arguments @('show',$TargetModel) } catch {
    Write-Host "[*] Base model missing from portable store; pulling..." -ForegroundColor Yellow
    Invoke-Ollama -OllamaHost $LocalHost -ModelStore $ModelStore -Arguments @('pull',$TargetModel)
}

