# Resolve which agents to process: ALL (default) or a single named agent.
$AgentName = $AgentName.Trim()
if ([string]::IsNullOrWhiteSpace($AgentName)) {
    $TargetAgents = $agents
    Write-Host "[*] Install mode: ALL agents ($($agents.Count))" -ForegroundColor Cyan
} else {
    $match = $agents | Where-Object { $_ -eq $AgentName }
    if (-not $match) {
        $suggestions = $agents | Where-Object { $_ -like "*$AgentName*" } | Select-Object -First 10
        Write-Host "[!] Agent '$AgentName' was not found among the $($agents.Count) available agents." -ForegroundColor Red
        if ($suggestions) {
            Write-Host "[i] Did you mean one of these?" -ForegroundColor Yellow
            $suggestions | ForEach-Object { Write-Host "  - $_" -ForegroundColor Yellow }
        }
        throw "Unknown agent name: $AgentName"
    }
    $TargetAgents = @($match)
    Write-Host "[*] Install mode: SINGLE agent ($AgentName)" -ForegroundColor Cyan
}

$Generated = 0
$RegisteredLocal = 0
$Failed = New-Object System.Collections.Generic.List[string]

foreach ($agent in $TargetAgents) {
    $directive = $agentDirectives[$agent]
    if (-not $directive) {
        Write-Warning "[!] Directive for agent '$agent' not found. Skipping."
        $Failed.Add("$agent (missing directive)")
        continue
    }

    # Same Modelfile layout as install_models.bat / prior working installer:
    #   <project>\\Modfiles\\Modelfile_<agent>
    # SYSTEM is double-quoted (working format from when tone matched directives).
    $modelfileContent = "FROM $TargetModel`nSYSTEM `"$directive`"`nPARAMETER temperature 0.7"
    $fileName = "Modelfile_$agent"
    $filePath = Join-Path $ModfileDir $fileName
    Set-Content -Path $filePath -Value $modelfileContent -Encoding UTF8
    $Generated++

    Write-Host "[$Generated/$($TargetAgents.Count)] Registering $agent on portable 11435..." -ForegroundColor DarkYellow
    try {
        Invoke-Ollama -OllamaHost $LocalHost -ModelStore $ModelStore -Arguments @('create',$agent,'-f',$filePath)
        $RegisteredLocal++
    } catch {
        Write-Host "[!] Portable registration failed for $agent : $($_.Exception.Message)" -ForegroundColor Red
        Write-Host "[!] Portable registration failed for $agent : $($_.Exception.Message)" -ForegroundColor Red
        $Failed.Add("$agent (portable)")
    }
}

$manifest = [pscustomobject]@{
    generated_at = (Get-Date).ToString('o')
    target_model = $TargetModel
    install_mode = if ($AgentName) { "single:$AgentName" } else { "all" }
    modfile_folder = $ModfileDir
    local_host = $LocalHost
    model_store = $ModelStore
    generated = $Generated
    registered_local = $RegisteredLocal
    failed = @($Failed)
}
$manifestPath = if ($AgentName) { Join-Path $ModfileDir "manifest_$AgentName.json" } else { Join-Path $ModfileDir 'manifest.json' }
$manifest | ConvertTo-Json -Depth 5 | Set-Content -Path $manifestPath -Encoding UTF8

Write-Host ""
Write-Host "=============================================================" -ForegroundColor Cyan
Write-Host "PORTABLE INSTALLATION COMPLETE" -ForegroundColor Green
Write-Host "Modfiles generated : $Generated / $($TargetAgents.Count)" -ForegroundColor White
Write-Host "Registered         : $RegisteredLocal / $Generated" -ForegroundColor White
Write-Host "Modfile folder     : $ModfileDir" -ForegroundColor White
Write-Host "Model store        : $ModelStore" -ForegroundColor White
if ($Failed.Count -gt 0) {
    Write-Host "Failures           : $($Failed.Count)" -ForegroundColor Yellow
    $Failed | ForEach-Object { Write-Host "  - $_" -ForegroundColor Yellow }
    exit 2
}
if ($AgentName) {
    Write-Host "Agent '$AgentName' is registered on the CypraTeam portable Ollama endpoint only." -ForegroundColor Green
} else {
    Write-Host "All available agents are registered on the CypraTeam portable Ollama endpoint only." -ForegroundColor Green
}
Write-Host "To list them: set `$env:OLLAMA_HOST='127.0.0.1:11435'; `$env:OLLAMA_MODELS='$ModelStore'; ollama list" -ForegroundColor DarkGray